import{_ as e,o as l,c as o,a2 as t}from"./chunks/framework.CZGNF-7T.js";const _=JSON.parse('{"title":"결재 위임 (대결 관리)","description":"","frontmatter":{},"headers":[],"relativePath":"approval/delegation.md","filePath":"approval/delegation.md","lastUpdated":1787994700000}'),i={name:"approval/delegation.md"};function r(n,a,s,d,c,p){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="결재-위임-대결-관리" tabindex="-1">결재 위임 (대결 관리) <a class="header-anchor" href="#결재-위임-대결-관리" aria-label="Permalink to &quot;결재 위임 (대결 관리)&quot;">​</a></h1><p>결재권자가 휴가, 출장, 병가 등으로 자리를 비울 때 업무 지연을 방지하기 위해 대리 결재자(대결자)를 지정하여 결재 권한을 위임할 수 있습니다.</p><h2 id="_1-결재-위임-설정-방법" tabindex="-1">1. 결재 위임 설정 방법 <a class="header-anchor" href="#_1-결재-위임-설정-방법" aria-label="Permalink to &quot;1. 결재 위임 설정 방법&quot;">​</a></h2><ol><li>좌측 메뉴에서 **<code>전자 결재 관리</code> $\\to$ <code>결재 위임 관리</code>**로 이동합니다.</li><li><code>[위임 등록]</code> 버튼을 클릭합니다.</li><li>아래 필수 항목을 입력 후 저장합니다: <ul><li><strong>대결자 (위임 대상자)</strong>: 본인을 대신하여 결재를 수행할 직원을 선택합니다.</li><li><strong>위임 기간</strong>: 시작일자와 종료일자를 지정합니다. (기간 내에만 대결 권한이 활성화됩니다.)</li><li><strong>위임 사유</strong>: 출장, 연차 휴가 등 사유를 입력합니다.</li></ul></li></ol><h2 id="_2-대결-프로세스-및-시스템-동작" tabindex="-1">2. 대결 프로세스 및 시스템 동작 <a class="header-anchor" href="#_2-대결-프로세스-및-시스템-동작" aria-label="Permalink to &quot;2. 대결 프로세스 및 시스템 동작&quot;">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>[기안 상신] ──▶ [원 결재자 부재] ──▶ [대결자에게 동시 알림] ──▶ [대결자 승인] ──▶ [대결 표기 및 다음 단계]</span></span></code></pre></div><ul><li><strong>대결자 알림 수신</strong>: 결재 요청이 발생하면 원 결재자뿐만 아니라 유효 기간 내의 <strong>대결자에게도 결재 요청 알림이 발송</strong>됩니다.</li><li><strong>결재 대기함 노출</strong>: 대결자의 <code>결재 대기함</code>에 대리 결재 대상 문서가 표시됩니다.</li><li><strong>대결 승인 처리</strong>: <ul><li>대결자가 문서를 열람하고 승인할 수 있습니다.</li><li>결재 이력 및 타임라인에 <strong><code>대결: 홍길동 (원 결재자: 김팀장)</code></strong> 형태로 명확히 기록됩니다.</li></ul></li><li><strong>기간 만료 시 자동 해제</strong>: 설정된 종료일자가 지나면 대결 권한은 자동으로 만료되어 안전하게 통제됩니다.</li></ul><h2 id="_3-유의-사항" tabindex="-1">3. 유의 사항 <a class="header-anchor" href="#_3-유의-사항" aria-label="Permalink to &quot;3. 유의 사항&quot;">​</a></h2><ul><li>대결자가 이미 승인 또는 반려한 결재 건은 원 결재자가 중복으로 처리할 수 없습니다.</li><li>관리자(<code>Superuser</code>)는 필요 시 특정 임직원의 부재를 대비하여 대리인을 사전에 직권으로 등록할 수 있습니다.</li></ul>',9)])])}const u=e(i,[["render",r]]);export{_ as __pageData,u as default};
